namespace WorldClockSettings;

// Checks zone ids against what the gadget can resolve. The gadget maps IANA
// names to Windows time zones through the same CLDR table (WindowsZoneMap,
// generated by tools/gen-windows-zones.ps1), accepting only the exact spelling,
// and needs that Windows zone to exist on this machine.
public static class TimeZoneIds
{
    // Resolves `id` to the IANA name the gadget accepts. Matches names
    // case-insensitively and reports the table's spelling, so a lowercase entry
    // can be stored as the gadget needs. Windows ids ("Tokyo Standard Time")
    // are not IANA names, and the gadget does not take them.
    public static bool TryNormalize(string id, out string canonical)
    {
        canonical = "";
        if (string.IsNullOrWhiteSpace(id)) return false;
        var match = WindowsZoneMap.Zones.FirstOrDefault(
            z => string.Equals(z.Key, id, StringComparison.OrdinalIgnoreCase));
        if (match.Key == null || !TimeZoneInfo.TryFindSystemTimeZoneById(match.Value, out _))
            return false;
        canonical = match.Key;
        return true;
    }

    // True when the gadget can resolve `id` exactly as written.
    public static bool IsValid(string id) =>
        TryNormalize(id, out var canonical) && string.Equals(canonical, id, StringComparison.Ordinal);
}
